import React, { useState, useMemo } from 'react';
import { useInventoryItems } from './hooks';
import { InventoryItem } from './types';
import { InventoryDashboard } from './components/InventoryDashboard';
import { InventoryFilterBar } from './components/InventoryFilterBar';
import { InventoryTable } from './components/InventoryTable';
import { HistoryDrawer } from './components/HistoryDrawer';
import { StockAdjustmentDialog } from './components/StockAdjustmentDialog';
import { LowStockPanel } from './components/LowStockPanel';
import { ErrorBoundary } from 'react-error-boundary';

export const InventoryPage: React.FC = () => {
  const { data, isLoading } = useInventoryItems();
  const items = data?.data || [];

  // Filter State
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('');
  const [status, setStatus] = useState('');

  // UI State
  const [selectedItem, setSelectedItem] = useState<InventoryItem | null>(null);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [isAdjustmentOpen, setIsAdjustmentOpen] = useState(false);

  // Derived Data
  const categories = useMemo(() => Array.from(new Set(items.map(i => i.category))), [items]);

  const filteredItems = useMemo(() => {
    return items.filter((item) => {
      const matchesSearch = item.description.toLowerCase().includes(search.toLowerCase()) || 
                            item.item_code.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = category ? item.category === category : true;
      const matchesStatus = status ? item.status === status : true;
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [items, search, category, status]);

  const summary = useMemo(() => {
    return {
      totalItems: items.length,
      lowStockCount: items.filter(i => i.status === 'LOW_STOCK').length,
      outOfStockCount: items.filter(i => i.status === 'OUT_OF_STOCK').length,
      inventoryValue: items.reduce((acc, item) => acc + (item.current_stock * item.unit_cost), 0)
    };
  }, [items]);

  // Handlers
  const handleRowClick = (item: InventoryItem) => {
    setSelectedItem(item);
    setIsDrawerOpen(true);
  };

  const handleAdjustStock = () => {
    setIsDrawerOpen(false);
    setIsAdjustmentOpen(true);
  };

  const ErrorFallback = ({ error, resetErrorBoundary }: any) => (
    <div className="bg-red-50 p-6 rounded-lg border border-red-200">
      <h2 className="text-red-800 font-semibold mb-2">Failed to render inventory module</h2>
      <pre className="text-xs text-red-600 mb-4 overflow-auto">{error.message}</pre>
      <button onClick={resetErrorBoundary} className="bg-red-100 text-red-800 px-4 py-2 rounded-md font-medium hover:bg-red-200">
        Try again
      </button>
    </div>
  );

  return (
    <ErrorBoundary FallbackComponent={ErrorFallback} onReset={() => { setSearch(''); setCategory(''); setStatus(''); }}>
      <div className="space-y-4 pb-12">
        <div>
          <h1 className="text-2xl font-semibold text-gray-900">Inventory Management</h1>
          <p className="mt-1 text-sm text-gray-500">
            Monitor stock levels, track consumption, and manage adjustments.
          </p>
        </div>

        <InventoryDashboard
          totalItems={summary.totalItems}
          lowStockCount={summary.lowStockCount}
          outOfStockCount={summary.outOfStockCount}
          inventoryValue={summary.inventoryValue}
        />

        <div className="flex flex-col lg:flex-row gap-6 items-start">
          <div className="flex-1 w-full space-y-4">
            <InventoryFilterBar
              search={search}
              onSearchChange={setSearch}
              category={category}
              onCategoryChange={setCategory}
              status={status}
              onStatusChange={setStatus}
              categories={categories}
            />

            <InventoryTable
              data={filteredItems}
              isLoading={isLoading}
              onRowClick={handleRowClick}
            />
          </div>

          <div className="w-full lg:w-80 shrink-0">
            <LowStockPanel 
              items={items} 
              onItemClick={(item) => {
                setSelectedItem(item);
                setIsAdjustmentOpen(true);
              }}
            />
          </div>
        </div>

        <HistoryDrawer
          item={selectedItem}
          isOpen={isDrawerOpen}
          onClose={() => setIsDrawerOpen(false)}
          onAdjustStock={handleAdjustStock}
        />

        <StockAdjustmentDialog
          item={selectedItem}
          isOpen={isAdjustmentOpen}
          onClose={() => setIsAdjustmentOpen(false)}
        />
      </div>
    </ErrorBoundary>
  );
};

import { apiRequest } from '../../api/client';
import { storage } from '../../utils/storage';
import { InventoryItem, StockTransactionRequest } from './types';

// The API endpoints as defined in docs/API.md
export const fetchInventoryItems = async (): Promise<{ success: boolean; data: InventoryItem[] }> => {
  const token = storage.getToken();
  // We assume the API returns { success: true, data: InventoryItem[] }
  return apiRequest<{ success: boolean; data: InventoryItem[] }>(`/api/v1/inventory/items`, {
    method: 'GET',
    token,
  });
};

export const submitStockTransaction = async (request: StockTransactionRequest): Promise<{ success: boolean; data: any }> => {
  const token = storage.getToken();
  return apiRequest<{ success: boolean; data: any }>(`/api/v1/inventory/transactions`, {
    method: 'POST',
    token,
    body: JSON.stringify(request),
  });
};

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { InventoryItem } from '../types';
import { X, History, TrendingDown, TrendingUp, AlertCircle } from 'lucide-react';
import { formatCurrency } from '../../../utils/formatters';

interface HistoryDrawerProps {
  item: InventoryItem | null;
  isOpen: boolean;
  onClose: () => void;
  onAdjustStock: () => void;
}

export const HistoryDrawer: React.FC<HistoryDrawerProps> = ({ item, isOpen, onClose, onAdjustStock }) => {
  if (!item) return null;

  // Since we don't have a dedicated endpoint for historical item transactions yet, 
  // we will mock a timeline to fulfill the ERP requirement for this module phase.
  const mockHistory = [
    { id: 1, type: 'MANUAL_DEDUCTION', qty: -50, date: '2 hours ago', reason: 'Order #10023 consumption' },
    { id: 2, type: 'MANUAL_DEDUCTION', qty: -20, date: 'Yesterday', reason: 'Order #10018 consumption' },
    { id: 3, type: 'RESTOCK', qty: 500, date: '3 days ago', reason: 'Received shipment from supplier' },
    { id: 4, type: 'WASTAGE', qty: -5, date: 'Last week', reason: 'Damaged during transit' },
  ];

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-gray-500 bg-opacity-75 z-30"
          />

          <motion.div
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            transition={{ type: 'spring', damping: 25, stiffness: 200 }}
            className="fixed inset-y-0 right-0 max-w-md w-full bg-white shadow-xl z-40 flex flex-col"
          >
            {/* Header */}
            <div className="px-6 py-4 border-b border-gray-200 flex items-center justify-between bg-gray-50">
              <div>
                <h2 className="text-xl font-bold text-gray-900">{item.item_code}</h2>
                <p className="text-sm text-gray-500">{item.description}</p>
              </div>
              <button
                onClick={onClose}
                className="rounded-md bg-white text-gray-400 hover:text-gray-500 focus:outline-none focus:ring-2 focus:ring-indigo-500"
              >
                <X className="h-6 w-6" aria-hidden="true" />
              </button>
            </div>

            {/* Content */}
            <div className="flex-1 overflow-y-auto p-6 space-y-8">

