import React from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { InventoryItem, TransactionType } from '../types';
import { useStockAdjustment } from '../hooks';
import { X } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const adjustmentSchema = z.object({
  transaction_type: z.enum(['RESTOCK', 'MANUAL_DEDUCTION', 'WASTAGE', 'CORRECTION']),
  quantity_change: z.number().int().min(1, 'Quantity must be at least 1'),
  reason: z.string().min(3, 'Please provide a valid reason'),
});

type AdjustmentFormData = z.infer<typeof adjustmentSchema>;

interface StockAdjustmentDialogProps {
  item: InventoryItem | null;
  isOpen: boolean;
  onClose: () => void;
}

export const StockAdjustmentDialog: React.FC<StockAdjustmentDialogProps> = ({ item, isOpen, onClose }) => {
  const { mutateAsync, isPending } = useStockAdjustment();

  const {
    register,
    handleSubmit,
    reset,
    watch,
    formState: { errors },
  } = useForm<AdjustmentFormData>({
    resolver: zodResolver(adjustmentSchema),
    defaultValues: {
      transaction_type: 'RESTOCK',
      quantity_change: 1,
      reason: '',
    },
  });

  const transactionType = watch('transaction_type');

  const onSubmit = async (data: AdjustmentFormData) => {
    if (!item) return;

    // Negate quantity if it's a deduction
    const finalQuantity = (data.transaction_type === 'RESTOCK' || data.transaction_type === 'CORRECTION')
      ? data.quantity_change
      : -data.quantity_change;

    await mutateAsync({
      item_id: item.id,
      transaction_type: data.transaction_type,
      quantity_change: finalQuantity,
      reason: data.reason,
    });
    reset();
    onClose();
  };

  if (!item) return null;

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-gray-500 bg-opacity-75 z-40"
          />

          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.95 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-0"
          >
            <div className="bg-white rounded-lg shadow-xl max-w-lg w-full overflow-hidden">
              <div className="px-6 py-4 border-b border-gray-200 flex items-center justify-between">
                <h3 className="text-lg font-semibold text-gray-900">Adjust Stock</h3>
                <button onClick={onClose} className="text-gray-400 hover:text-gray-500">
                  <X className="h-5 w-5" />
                </button>
              </div>

              <div className="px-6 py-4 bg-gray-50 border-b border-gray-200">
                <p className="text-sm font-medium text-gray-900">{item.description}</p>
                <p className="text-sm text-gray-500">Current Stock: {item.current_stock} {item.unit}</p>
              </div>

              <form onSubmit={handleSubmit(onSubmit)} className="p-6 space-y-4">
                <div>
                  <label className="block text-sm font-medium leading-6 text-gray-900">Action Type</label>
                  <select
                    {...register('transaction_type')}
                    className="mt-2 block w-full rounded-md border-0 py-1.5 pl-3 pr-10 text-gray-900 ring-1 ring-inset ring-gray-300 focus:ring-2 focus:ring-indigo-600 sm:text-sm sm:leading-6"
                  >
                    <option value="RESTOCK">Add Stock (Restock)</option>
                    <option value="MANUAL_DEDUCTION">Remove Stock (Manual)</option>
                    <option value="WASTAGE">Record Wastage</option>
                    <option value="CORRECTION">Inventory Correction</option>
                  </select>
                  {errors.transaction_type && <p className="mt-1 text-sm text-red-600">{errors.transaction_type.message}</p>}
                </div>

                <div>
                  <label className="block text-sm font-medium leading-6 text-gray-900">
                    Quantity {transactionType === 'RESTOCK' ? 'to Add' : 'to Remove'}
                  </label>
                  <input
                    type="number"
                    {...register('quantity_change', { valueAsNumber: true })}
                    className="mt-2 block w-full rounded-md border-0 py-1.5 text-gray-900 ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-indigo-600 sm:text-sm sm:leading-6"
                  />
                  {errors.quantity_change && <p className="mt-1 text-sm text-red-600">{errors.quantity_change.message}</p>}
                </div>

                <div>
                  <label className="block text-sm font-medium leading-6 text-gray-900">Reason / Notes</label>
                  <textarea
                    {...register('reason')}
                    rows={3}
                    className="mt-2 block w-full rounded-md border-0 py-1.5 text-gray-900 ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-indigo-600 sm:text-sm sm:leading-6"
                    placeholder="E.g., Received shipment from supplier..."
                  />
                  {errors.reason && <p className="mt-1 text-sm text-red-600">{errors.reason.message}</p>}
                </div>

                <div className="mt-6 flex justify-end gap-3">
                  <button
                    type="button"
                    onClick={onClose}
                    className="rounded-md bg-white px-3 py-2 text-sm font-semibold text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 hover:bg-gray-50"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={isPending}
                    className="rounded-md bg-indigo-600 px-3 py-2 text-sm font-semibold text-white shadow-sm hover:bg-indigo-500 disabled:opacity-50"
                  >
                    {isPending ? 'Saving...' : 'Confirm Adjustment'}
                  </button>
                </div>
              </form>
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
};

import React, { useState } from 'react';
import { useOrders, useOrder } from './hooks';
import { OrderQueryOptions, Order } from './types';
import { OrdersTable } from './components/OrdersTable';
import { OrdersFilterBar } from './components/OrdersFilterBar';
import { OrderDetailDrawer } from './components/OrderDetailDrawer';
import { BulkActions } from './components/BulkActions';
import { ErrorBoundary } from 'react-error-boundary';

export const OrdersPage: React.FC = () => {
  // Query State
  const [queryOptions, setQueryOptions] = useState<OrderQueryOptions>({
    page: 1,
    limit: 50,
    status: '',
    search: '',
    start_date: '',
    end_date: '',
  });

  // Fetch paginated list
  const { data, isLoading } = useOrders(queryOptions);

  // Selection state
  const [selectedRowIds, setSelectedRowIds] = useState<Set<string>>(new Set());

  // Drawer state
  const [drawerOrderId, setDrawerOrderId] = useState<string | null>(null);
  const { data: drawerOrder } = useOrder(drawerOrderId);

  // Handlers
  const handleToggleRow = (id: string) => {
    const newSet = new Set(selectedRowIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedRowIds(newSet);
  };

  const handleToggleAll = (ids: string[]) => {
    if (selectedRowIds.size === ids.length && ids.length > 0) {
      setSelectedRowIds(new Set());
    } else {
      setSelectedRowIds(new Set(ids));
    }
  };

  const ErrorFallback = ({ error, resetErrorBoundary }: any) => (
    <div className="bg-red-50 p-6 rounded-lg border border-red-200">
      <h2 className="text-red-800 font-semibold mb-2">Failed to render orders module</h2>
      <pre className="text-xs text-red-600 mb-4 overflow-auto">{error.message}</pre>
      <button onClick={resetErrorBoundary} className="bg-red-100 text-red-800 px-4 py-2 rounded-md font-medium hover:bg-red-200">
        Try again
      </button>
    </div>
  );

  return (
    <ErrorBoundary FallbackComponent={ErrorFallback} onReset={() => setQueryOptions({ ...queryOptions, page: 1 })}>
      <div className="space-y-4 relative pb-20">
        <div className="flex justify-between items-center mb-6">
          <div>
            <h1 className="text-2xl font-semibold text-gray-900">Orders Management</h1>
            <p className="mt-1 text-sm text-gray-500">
              View, search, and manage all print orders in real-time.
            </p>
          </div>
        </div>

        <OrdersFilterBar
          search={queryOptions.search || ''}
          onSearchChange={(val) => setQueryOptions({ ...queryOptions, search: val, page: 1 })}
          status={queryOptions.status || ''}
          onStatusChange={(val) => setQueryOptions({ ...queryOptions, status: val, page: 1 })}
          startDate={queryOptions.start_date || ''}
          onStartDateChange={(val) => setQueryOptions({ ...queryOptions, start_date: val, page: 1 })}
          endDate={queryOptions.end_date || ''}
          onEndDateChange={(val) => setQueryOptions({ ...queryOptions, end_date: val, page: 1 })}
        />

        <OrdersTable
          orders={data?.data || []}
          isLoading={isLoading}
          onRowClick={(order) => setDrawerOrderId(order.id)}
          selectedRowIds={selectedRowIds}
          onToggleRow={handleToggleRow}
          onToggleAll={handleToggleAll}
        />

        {/* Server-side Pagination Controls */}
        {data && data.total_pages > 1 && (
          <div className="flex items-center justify-between border-t border-gray-200 bg-white px-4 py-3 sm:px-6 shadow-sm sm:rounded-lg">
            <div className="hidden sm:flex sm:flex-1 sm:items-center sm:justify-between">
              <div>
                <p className="text-sm text-gray-700">
                  Showing <span className="font-medium">{(data.page - 1) * data.limit + 1}</span> to{' '}
                  <span className="font-medium">{Math.min(data.page * data.limit, data.total)}</span> of{' '}
                  <span className="font-medium">{data.total}</span> results
                </p>
              </div>
              <div>
                <nav className="isolate inline-flex -space-x-px rounded-md shadow-sm" aria-label="Pagination">
                  <button
                    onClick={() => setQueryOptions({ ...queryOptions, page: Math.max(1, queryOptions.page - 1) })}
                    disabled={queryOptions.page === 1}
                    className="relative inline-flex items-center rounded-l-md px-2 py-2 text-gray-400 ring-1 ring-inset ring-gray-300 hover:bg-gray-50 focus:z-20 focus:outline-offset-0 disabled:opacity-50"
                  >
                    Previous
                  </button>
                  <button
                    onClick={() => setQueryOptions({ ...queryOptions, page: Math.min(data.total_pages, queryOptions.page + 1) })}
                    disabled={queryOptions.page === data.total_pages}
                    className="relative inline-flex items-center rounded-r-md px-2 py-2 text-gray-400 ring-1 ring-inset ring-gray-300 hover:bg-gray-50 focus:z-20 focus:outline-offset-0 disabled:opacity-50"
                  >
                    Next
                  </button>
                </nav>
              </div>
            </div>
          </div>
        )}

        <OrderDetailDrawer
          isOpen={!!drawerOrderId}
          onClose={() => setDrawerOrderId(null)}
          order={drawerOrder || null}
        />

        <BulkActions
          selectedIds={Array.from(selectedRowIds)}
          onClearSelection={() => setSelectedRowIds(new Set())}
        />
      </div>
    </ErrorBoundary>
  );
};

